using CosmicShore.Gameplay;
using NUnit.Framework;
using UnityEngine;

namespace CosmicShore.Tests
{
    /// <summary>
    /// <see cref="AnglerCommandMath"/> against the Angler Command Lab page (<c>Docs/Studios/AnglerCommandLab.html</c>, the
    /// <c>CORE</c> block its model calls). The tables below are GENERATED by
    /// <c>Tools/Build/angler_command_parity/goldens.cjs</c> from the page's own functions, so a change to either side that
    /// the other does not follow fails here; <c>Tools/Build/angler_command_parity/run.sh</c> runs this file outside Unity
    /// and plants formula changes this test must catch. A few named behaviours sit above the tables, for a reader.
    /// </summary>
    [TestFixture]
    public class AnglerCommandMathTests
    {
        const float Tol = 1e-3f;

        [Test]
        public void BrushScale_FullPullPaintsTheWholeBrush_AndAJustPressedTriggerPaintsTheLightBrush()
        {
            Assert.AreEqual(1f, AnglerCommandMath.BrushScale(1f, 0.35f), Tol);
            Assert.AreEqual(0.35f, AnglerCommandMath.BrushScale(0.5f, 0.35f), Tol);
            Assert.AreEqual(1f, AnglerCommandMath.BrushScale(0.6f, 1f), Tol, "brushMin 1 = the depth does not matter");
        }

        [Test]
        public void PickTarget_SpreadsASquadOverAPaintedSet_ByTheClaimsAlreadyOnEachPrism()
        {
            var cands = new[] { new Vector3(10f, 0f, 0f), new Vector3(20f, 0f, 0f) };
            Assert.AreEqual(0, AnglerCommandMath.PickTarget(Vector3.zero, cands, new[] { 0, 0 }), "nearest when nobody has claimed it");
            Assert.AreEqual(1, AnglerCommandMath.PickTarget(Vector3.zero, cands, new[] { 1, 0 }), "one claim (900) outweighs 300 of distance squared");
            Assert.AreEqual(-1, AnglerCommandMath.PickTarget(Vector3.zero, new Vector3[0], new int[0]));
        }

        [Test]
        public void TameStep_FillsInTheLightAndFadesOutsideIt_NeverBelowZero()
        {
            Assert.AreEqual(0.4f, AnglerCommandMath.TameStep(0f, true, 1f, 2.5f, 0.6f), Tol);
            Assert.AreEqual(0f, AnglerCommandMath.TameStep(0.1f, false, 1f, 2.5f, 0.6f), Tol);
        }

        [Test]
        public void EveryFunction_MatchesTheLabPage()
        {
            foreach (var c in BrushCases)
                Assert.AreEqual(c.want, AnglerCommandMath.BrushScale(c.depth, c.brushMin), Tol, $"BrushScale({c.depth}, {c.brushMin})");
            foreach (var c in ConeCases)
                Assert.AreEqual(c.want, AnglerCommandMath.InCone(c.o, c.f, c.p, c.cone, c.reach), $"InCone {c.p} cone {c.cone} reach {c.reach}");
            foreach (var c in PickCases)
                Assert.AreEqual(c.want, AnglerCommandMath.PickTarget(c.from, c.candidates, c.claims), $"PickTarget from {c.from}");
            foreach (var c in SlotCases)
                Near(c.want, AnglerCommandMath.FormationSlot(c.i, c.p, c.f, c.r, c.u, c.back), $"FormationSlot({c.i})");
            foreach (var c in FollowCases)
                Assert.AreEqual(c.want, AnglerCommandMath.FollowSpeed(c.hull, c.gap, c.min, c.cap), Tol, $"FollowSpeed({c.hull}, {c.gap}, {c.min}, {c.cap})");
            foreach (var c in LightCapCases)
                Assert.AreEqual(c.want, AnglerCommandMath.LightFollowCap(c.max, c.aggression, c.tow), Tol, "LightFollowCap");
            foreach (var c in TadCapCases)
                Assert.AreEqual(c.want, AnglerCommandMath.TadFollowCap(c.max, c.hunt, c.tick, c.gap, c.tow), Tol, $"TadFollowCap gap {c.gap}");
            foreach (var c in GatherCases)
                Assert.AreEqual(c.want, AnglerCommandMath.GatherSpeed(c.d, c.min, c.top, c.hull), Tol, $"GatherSpeed({c.d})");
            foreach (var c in TameCases)
                Assert.AreEqual(c.want, AnglerCommandMath.TameStep(c.tame, c.hold, c.dt, c.tameTime, c.decay), Tol, $"TameStep({c.tame}, {c.hold})");
            foreach (var c in LureCases)
                Near(c.want, AnglerCommandMath.LurePoint(c.p, c.f, c.u, c.ahead), $"LurePoint({c.ahead})");
        }

        static void Near(Vector3 want, Vector3 have, string what)
        {
            Assert.AreEqual(want.x, have.x, Tol, what + " x");
            Assert.AreEqual(want.y, have.y, Tol, what + " y");
            Assert.AreEqual(want.z, have.z, Tol, what + " z");
        }

